SELECT item.*,song.source_id,song.relative_path,song.file_size,song.modified_at,meta.fingerprint AS metadata_fingerprint,meta.fields_json AS metadata_fields FROM metadata_item item LEFT JOIN media_song song ON song.id=item.song_id LEFT JOIN song_metadata meta ON meta.song_id=item.song_id WHERE item.batch_id=@{batchId} AND (@{status} IS NULL OR item.status=@{status} OR (@{status}='APPLIED' AND item.status IN ('AUTO_APPLIED','MANUAL_APPLIED'))) AND (@{keyword} IS NULL OR LOWER(item.title) LIKE LOWER(@{keyword}) ESCAPE '!' OR LOWER(item.artists_json) LIKE LOWER(@{keyword}) ESCAPE '!') ORDER BY CASE WHEN @{sort}='TITLE' THEN item.title END ASC, CASE WHEN @{sort}='SCORE_DESC' THEN CAST(JSON_EXTRACT(item.candidates_json,'$[0].score') AS DECIMAL(10,5)) END DESC, CASE WHEN @{sort}='UPDATED_DESC' THEN item.updated_at END DESC,item.id ASC LIMIT @{limit} OFFSET @{offset}
